mapper.update:
update dinner_table
update_user = #{updateUser}, update_time = #{updateTime}, table_number = #{tableNumber}, capacity = #{capacity}, status = #{status}, qr_code_url = #{qrCodeUrl}
where id = #{id}

mapper.select:
select id, table_number, capacity, status, qr_code_url, create_time, update_time, create_user, update_user from dinner_table
and table_number = #{tableNumber}
and status = #{status}
order by table_number asc
